const input = $json || {};
return [{
  json: {
    requestText: input.requestText || input.text || input.message || 'Bu akşam ne yapayım?',
    userContext: input.userContext || {},
    calendarContext: input.calendarContext || {}
  }
}];

const incoming = $json || {};

const requestText = String(
  incoming.requestText ??
  incoming.text ??
  incoming.message ??
  'Bu akşam ne yapayım?'
).trim();

const userContext = incoming.userContext ?? {};
const calendarContext = incoming.calendarContext ?? {};
const normalized = requestText
  .toLocaleLowerCase('tr-TR')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const routeDefinitions = [
  {
    route: 'calendar_action',
    agentWorkflowName: 'Concierge OS - Calendar Approval',
    priority: 100,
    keywords: [
      'takvime ekle', 'calendar ekle', 'add to calendar', 'randevu ekle',
      'etkinligi ekle', 'eventi ekle', 'takvimden sil', 'takvimi guncelle',
      'reschedule', 'yeniden planla'
    ],
    needsDiscovery: false,
    requiresApproval: true,
    requiredContext: ['calendar']
  },
  {
    route: 'weekly_planner',
    agentWorkflowName: 'Concierge OS - Weekly Planner',
    priority: 95,
    keywords: [
      'haftami planla', 'haftayi planla', 'weekly plan', 'bu hafta plan',
      'gelecek hafta', 'next week', 'haftalik plan'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar', 'recommendation_history']
  },
  {
    route: 'daily_planner',
    agentWorkflowName: 'Concierge OS - Daily Planner',
    priority: 90,
    keywords: [
      'bu aksam ne yapayim', 'bugun ne yapayim', 'tonight', 'today plan',
      'aksam plani', 'gunumu planla', 'plan my day', 'bu gece'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar', 'weather', 'recommendation_history']
  },
  {
    route: 'social_discovery',
    agentWorkflowName: 'Concierge OS - Social Discovery Agent',
    priority: 85,
    keywords: [
      'sosyal etkinlik', 'networking', 'internations', 'meetup', 'event',
      'etkinlik bul', 'insanlarla tanis', 'yeni insan', 'jazz', 'stand up',
      'stand-up', 'mixer', 'social', 'arkadas edin', 'turk etkinligi'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar', 'recommendation_history']
  },
  {
    route: 'sports_fitness',
    agentWorkflowName: 'Concierge OS - Sports and Fitness Agent',
    priority: 84,
    keywords: [
      'boxing', 'boks', 'gym', 'spor', 'padel', 'tennis', 'yuzme',
      'swimming', 'walk', 'yuruyus', 'fitness', 'privilee', 'antrenman',
      'workout'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar', 'activity_history']
  },
  {
    route: 'style_grooming',
    agentWorkflowName: 'Concierge OS - Style and Grooming Coach',
    priority: 83,
    keywords: [
      'ne giyeyim', 'outfit', 'giyim', 'tarz', 'style', 'bakim',
      'grooming', 'sakal', 'sac', 'parfum', 'fragrance', 'skincare',
      'cilt bakimi', 'kombin'
    ],
    needsDiscovery: false,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar']
  },
  {
    route: 'social_confidence',
    agentWorkflowName: 'Concierge OS - Social Confidence Coach',
    priority: 82,
    keywords: [
      'kadinla konus', 'kadinlara yaklas', 'approach women', 'flirt',
      'flort', 'conversation', 'sohbet baslat', 'ozguven', 'confidence',
      'date hazirlik', 'dating', 'mesaj yaz', 'ne diyeyim'
    ],
    needsDiscovery: false,
    requiresApproval: false,
    requiredContext: ['memory']
  },
  {
    route: 'travel',
    agentWorkflowName: 'Concierge OS - Travel Scout',
    priority: 80,
    keywords: [
      'seyahat', 'travel', 'trip', 'weekend trip', 'hafta sonu kacamak',
      'ucuz ucus', 'flight', 'otel', 'hotel', 'oman', 'road trip',
      'tatil', 'destination'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar']
  },
  {
    route: 'career_learning',
    agentWorkflowName: 'Concierge OS - Career and Learning Coach',
    priority: 78,
    keywords: [
      'kariyer', 'career', 'cybersecurity', 'security architect',
      'ai ogren', 'learning', 'liderlik', 'leadership', 'public speaking',
      'is firsati', 'job', 'conference', 'sertifika'
    ],
    needsDiscovery: true,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar']
  },
  {
    route: 'finance',
    agentWorkflowName: 'Concierge OS - Finance Coach',
    priority: 76,
    keywords: [
      'finance review', 'finans', 'butce', 'budget', 'yatirim',
      'investment', 'harcama', 'expense', 'tasarruf', 'saving',
      'abonelik', 'subscription'
    ],
    needsDiscovery: false,
    requiresApproval: false,
    requiredContext: ['memory']
  },
  {
    route: 'feedback',
    agentWorkflowName: 'Concierge OS - Feedback Collector',
    priority: 74,
    keywords: [
      'begendim', 'begenmedim', 'etkinlik guzeldi', 'etkinlik kotuydu',
      'puan ver', 'rating', 'feedback', 'tekrar gitmem', 'tekrar giderim',
      'katildim', 'gitmedim'
    ],
    needsDiscovery: false,
    requiresApproval: false,
    requiredContext: ['memory', 'recommendation_history']
  },
  {
    route: 'profile_update',
    agentWorkflowName: 'Concierge OS - Memory Manager',
    priority: 72,
    keywords: [
      'bunu hatirla', 'tercihimi guncelle', 'artik istemiyorum',
      'daha az oner', 'daha cok oner', 'profilimi guncelle',
      'remember this', 'update my preference', 'seviyorum', 'sevmiyorum'
    ],
    needsDiscovery: false,
    requiresApproval: true,
    requiredContext: ['memory']
  }
];

const matches = [];

for (const def of routeDefinitions) {
  const matchedKeywords = def.keywords.filter(keyword =>
    normalized.includes(
      keyword
        .toLocaleLowerCase('tr-TR')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
    )
  );

  if (matchedKeywords.length > 0) {
    matches.push({
      ...def,
      matchedKeywords,
      matchCount: matchedKeywords.length,
      weightedScore: def.priority + (matchedKeywords.length * 5)
    });
  }
}

matches.sort((a, b) => b.weightedScore - a.weightedScore);

let selected;

if (matches.length) {
  selected = matches[0];
} else {
  selected = {
    route: 'general_concierge',
    agentWorkflowName: 'Concierge OS - General Concierge',
    priority: 40,
    matchedKeywords: [],
    matchCount: 0,
    weightedScore: 40,
    needsDiscovery: false,
    requiresApproval: false,
    requiredContext: ['memory', 'calendar']
  };
}

const confidence = selected.matchCount >= 3
  ? 0.98
  : selected.matchCount === 2
    ? 0.92
    : selected.matchCount === 1
      ? 0.82
      : 0.45;

const isAmbiguous =
  !matches.length ||
  (matches.length > 1 &&
   Math.abs(matches[0].weightedScore - matches[1].weightedScore) <= 3);

const safetyFlags = [];

if (/(satın al|odeme yap|pay now|book and pay|rezervasyon yap)/i.test(requestText)) {
  safetyFlags.push('external_transaction_requires_explicit_approval');
}

if (/(mesaj gonder|email gonder|send message|send email)/i.test(requestText)) {
  safetyFlags.push('external_communication_requires_explicit_approval');
}

if (/(sil|delete|cancel)/i.test(requestText)) {
  safetyFlags.push('destructive_action_requires_explicit_approval');
}

const actionMode =
  selected.requiresApproval || safetyFlags.length
    ? 'prepare_and_request_approval'
    : selected.needsDiscovery
      ? 'discover_analyze_recommend'
      : 'analyze_and_respond';

return [{
  json: {
    success: true,
    decision: {
      route: selected.route,
      agentWorkflowName: selected.agentWorkflowName,
      actionMode,
      confidence,
      isAmbiguous,
      needsDiscovery: selected.needsDiscovery,
      requiresApproval: selected.requiresApproval || safetyFlags.length > 0,
      requiredContext: selected.requiredContext,
      matchedKeywords: selected.matchedKeywords,
      safetyFlags
    },
    request: {
      originalText: requestText,
      normalizedText: normalized
    },
    contextReceived: {
      hasUserContext: Object.keys(userContext).length > 0,
      hasCalendarContext: Object.keys(calendarContext).length > 0
    },
    alternativeRoutes: matches.slice(1, 4).map(match => ({
      route: match.route,
      agentWorkflowName: match.agentWorkflowName,
      matchedKeywords: match.matchedKeywords,
      weightedScore: match.weightedScore
    }))
  }
}];
